beforeExample:
class Test {
    boolean process(String arg) {
        // Original code context
        return arg == null || Boolean.valueOf(arg).booleanValue();
    }
    boolean anotherMethod(String s) {
        // This method should not be affected by the cleanup
        Boolean b = Boolean.valueOf(s);
        return b; // Implicit unboxing, not .booleanValue() call
    }
}

afterExample:
class Test {
    boolean process(String arg) {
        // Transformed code
        return arg == null || Boolean.parseBoolean(arg);
    }
    boolean anotherMethod(String s) {
        // This method remains unchanged
        Boolean b = Boolean.valueOf(s);
        return b;
    }
}

negativeExample:
class Test {
    boolean process(String arg) {
        // Already uses parseBoolean, should not match
        return arg == null || Boolean.parseBoolean(arg);
    }
    boolean anotherMethod(String s) {
        // Explicitly getting a Boolean object, not calling booleanValue(), should not match
        Boolean b = java.lang.Boolean.valueOf(s);
        return b.equals(java.lang.Boolean.TRUE);
    }
}
